  `m1_dia` = VALUES(`m1_dia`),
  `m1_hr` = VALUES(`m1_hr`),
  `m2_sys` = VALUES(`m2_sys`),
  `m2_dia` = VALUES(`m2_dia`),
  `m2_hr` = VALUES(`m2_hr`),
  `n1_sys` = VALUES(`n1_sys`),
  `n1_dia` = VALUES(`n1_dia`),
  `n1_hr` = VALUES(`n1_hr`),
  `n2_sys` = VALUES(`n2_sys`),
  `n2_dia` = VALUES(`n2_dia`),
  `n2_hr` = VALUES(`n2_hr`);

